<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import Panel from '../components/Panel.vue'
import {api,busy,current,error,notify,refresh,run,select} from '../store'
interface Candidate {id:string;filename:string;page_group:string;sha256:string;split:string;seal_id?:string;preview_url:string}
interface Stroke {width:number;points:[number,number][]}
const candidates=ref<Candidate[]>([]),candidateId=ref(''),status=ref<any>(null)
const candidate=computed(()=>candidates.value.find(c=>c.id===candidateId.value))
const original=computed(()=>current.value?.artifacts.find(a=>a.kind==='original'))
const enhancement=computed(()=>current.value?.artifacts.filter(a=>a.kind==='enhancement').at(-1))
const annotator=ref(localStorage.getItem('yinmai-annotator')||''),transcription=ref(''),legibility=ref('unsure'),notes=ref('')
const strokes=ref<Stroke[]>([]),brush=ref(.03),drawing=ref(false),dirty=ref(false),loading=ref(false)
const canvas=ref<HTMLCanvasElement>(),saved=ref<any>(null)
const discardOpen=ref(false)
let active:Stroke|null=null,restoring=false,loadVersion=0
let pendingDiscard:Promise<boolean>|null=null,resolveDiscard:((value:boolean)=>void)|null=null
const model=computed(()=>status.value?.enhancement)
const maskStatus=computed(()=>strokes.value.length?`手绘掩膜 · ${strokes.value.length}笔`:'掩膜未标注')
const removeRouteGuard=useRouter().beforeEach(()=>confirmDiscard())
function markDirty(){dirty.value=true}
function confirmDiscard():Promise<boolean>{if(!dirty.value)return Promise.resolve(true);if(pendingDiscard)return pendingDiscard;discardOpen.value=true;pendingDiscard=new Promise(resolve=>resolveDiscard=resolve);return pendingDiscard}
function decideDiscard(discard:boolean){discardOpen.value=false;const resolve=resolveDiscard;resolveDiscard=null;pendingDiscard=null;resolve?.(discard)}
function paint(){const c=canvas.value;if(!c)return;const ctx=c.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle='rgba(0,215,209,.62)';ctx.fillStyle='rgba(0,215,209,.62)';ctx.lineCap='round';ctx.lineJoin='round'
 for(const stroke of strokes.value){ctx.lineWidth=Math.max(1,stroke.width*Math.min(c.width,c.height));ctx.beginPath();stroke.points.forEach(([x,y],i)=>i?ctx.lineTo(x*(c.width-1),y*(c.height-1)):ctx.moveTo(x*(c.width-1),y*(c.height-1)));ctx.stroke();for(const [x,y] of stroke.points){ctx.beginPath();ctx.arc(x*(c.width-1),y*(c.height-1),ctx.lineWidth/2,0,2*Math.PI);ctx.fill()}}}
function imageLoaded(e:Event){const img=e.target as HTMLImageElement;if(canvas.value){canvas.value.width=Math.min(2048,img.naturalWidth);canvas.value.height=Math.round(img.naturalHeight*canvas.value.width/img.naturalWidth);paint()}}
function point(e:PointerEvent):[number,number]{const b=canvas.value!.getBoundingClientRect();return [Math.min(1,Math.max(0,(e.clientX-b.left)/b.width)),Math.min(1,Math.max(0,(e.clientY-b.top)/b.height))]}
function start(e:PointerEvent){if(!drawing.value||loading.value||busy.value||!canvas.value||strokes.value.length>=80)return;e.preventDefault();canvas.value.setPointerCapture(e.pointerId);active={width:brush.value,points:[point(e)]};strokes.value.push(active);markDirty();paint()}
function move(e:PointerEvent){if(!active)return;e.preventDefault();if(active.points.length<1000&&strokes.value.reduce((n,s)=>n+s.points.length,0)<10000){active.points.push(point(e));paint()}}
function stop(){active=null}
function undo(){strokes.value.pop();markDirty();paint()}
async function fetchCorpus(){candidates.value=await api<Candidate[]>('/lab/corpus');if(!candidateId.value)candidateId.value=candidates.value[0]?.id||''}
async function importCandidate(){if(!candidate.value||!(await confirmDiscard()))return;const id=candidate.value.id;await run(async()=>{const seal=await api(`/lab/corpus/${id}/import`,{method:'POST'});dirty.value=false;await refresh();select(seal.id);await fetchCorpus();notify('原始裁图已载入，来源哈希与验证组标记已保留。')})}
function nextCandidate(){const index=candidates.value.findIndex(c=>c.id===candidateId.value);candidateId.value=candidates.value[(index+1)%candidates.value.length]?.id||''}
async function enhance(){await run(async()=>{if(!current.value||!original.value)throw new Error('请先载入或上传裁图');await api(`/seals/${current.value.id}/enhance`,{method:'POST',body:JSON.stringify({source_artifact_id:original.value.id})});await refresh();notify('实验去噪版本已生成；请与原图比较细笔画，不能据此认定缺笔恢复。')})}
async function save(){await run(async()=>{if(!current.value||!original.value)throw new Error('请先载入原图');stop();const result=await api(`/seals/${current.value.id}/annotations`,{method:'POST',body:JSON.stringify({source_artifact_id:original.value.id,source_sha256:original.value.metadata.sha256,annotator:annotator.value,transcription:transcription.value,legibility:legibility.value,notes:notes.value,mask_mode:strokes.value.length?'drawn':'unlabeled',strokes:strokes.value})});saved.value=result;dirty.value=false;localStorage.setItem('yinmai-annotator',annotator.value);await refresh();notify('人工草稿已保存到MySQL及版本文件，仍需独立复核。')})}
watch(()=>current.value?.id,async(id,previous)=>{if(restoring){restoring=false;return}if(!(await confirmDiscard())){restoring=true;select(previous||'__reference__');return}
 const version=++loadVersion;dirty.value=false;strokes.value=[];transcription.value='';legibility.value='unsure';notes.value='';saved.value=null;drawing.value=false;stop();await nextTick();paint();if(!id)return;loading.value=true
 try{const result=await api(`/seals/${id}/annotations/latest`);if(version!==loadVersion)return;saved.value=result;if(result.document){const d=result.document;annotator.value=d.annotator;transcription.value=d.transcription;legibility.value=d.legibility;notes.value=d.notes;strokes.value=d.strokes;await nextTick();paint()}}
 catch(e){error.value=e instanceof Error?e.message:'草稿读取失败'}finally{if(version===loadVersion)loading.value=false}
},{immediate:true})
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{[status.value]=await Promise.all([api('/lab/status'),fetchCorpus()])}catch(e){error.value=e instanceof Error?e.message:'实验室加载失败'}})
onBeforeUnmount(()=>{removeRouteGuard();window.removeEventListener('beforeunload',beforeUnload);decideDiscard(false)})
</script>
<template>
<div class="lab-intro"><div><span class="pill">图像增强实验 · 人工标注</span><p>去噪模型仅学习合成噪声，真实缺损与篆字识别尚未验证。原稿保留；人工记录只存为待复核草稿。</p></div><RouterLink class="button small" to="/projects">查看归档项目</RouterLink></div>
<div class="lab-grid">
<Panel title="首批标注素材" note="原裁图只读">
<template v-if="candidates.length"><label class="lab-field">候选图片<select v-model="candidateId" aria-label="候选图片"><option v-for="c in candidates" :key="c.id" :value="c.id">{{c.filename}}{{c.seal_id?' · 已载入':''}}</option></select></label><div class="candidate-preview"><img v-if="candidate" :src="candidate.preview_url" :alt="candidate.filename"></div><p class="lab-filename">{{candidate?.filename}}</p><dl class="data-list compact"><div><dt>来源页</dt><dd>{{candidate?.page_group}}</dd></div><div><dt>数据组</dt><dd>独立验证组</dd></div><div><dt>候选图片</dt><dd>{{candidates.length}} 张</dd></div><div><dt>已载入</dt><dd>{{candidates.filter(c=>c.seal_id).length}} 张</dd></div></dl><button class="primary full" :disabled="busy" @click="importCandidate">载入该图开始标注</button><button class="full" :disabled="busy" @click="nextCandidate">下一张候选图</button><p class="hint">这100张来自验证组。标注后仍保留分组，不自动加入训练；如需调整分组，须重新建立独立评估集。</p></template>
<div v-else class="empty-state">尚未配置本机标注素材。<RouterLink to="/upload">也可先上传自己的裁图</RouterLink></div>
</Panel>
<Panel title="原图与实验增强" note="原始像素与模型结果对照">
<template v-if="current&&original"><p class="lab-filename">当前工作图：{{current.filename}}</p><div class="lab-comparison"><figure><div><img :src="original.url" alt="未经增强的原始裁图"></div><figcaption>原始裁图 · 保留原稿</figcaption></figure><figure><div><img v-if="enhancement" :src="enhancement.url" alt="实际实验去噪结果"><span v-else>尚未生成</span></div><figcaption>{{enhancement?'实际去噪结果 · 非缺笔补全':'实验输出'}}</figcaption></figure></div><button class="primary full" :disabled="busy||!model?.available" @click="enhance">生成实验去噪版本</button><p class="hint">11,739参数CNN · GPU训练400步 · 本页实际执行模型推理。仅做图像去噪实验，可能平滑细笔画，须人工对照；不作为历史修复结论。</p><div class="lab-paint-heading"><h3>在原图上标记印迹</h3><span class="pill">{{maskStatus}}</span></div><p class="hint">青色为手绘印迹区域。请涂画实际可见的印文与边框；不确定时可只保存释文草稿。导出掩膜为白色印迹、黑色背景。</p><div class="lab-canvas" :class="{painting:drawing}"><img :src="original.url" alt="手工标注原始裁图" @load="imageLoaded"><canvas ref="canvas" aria-label="在原图上手绘印迹掩膜" @pointerdown="start" @pointermove="move" @pointerup="stop" @pointercancel="stop" @lostpointercapture="stop"></canvas></div><div class="lab-tools"><label><input type="checkbox" v-model="drawing" :disabled="busy||loading" aria-label="启用手绘掩膜">启用手绘</label><label>笔刷<input type="range" min="0.005" max="0.12" step="0.005" v-model.number="brush" aria-label="掩膜笔刷宽度"></label><button :disabled="!strokes.length||busy||loading" @click="undo">撤销一笔</button></div></template>
<div v-else class="empty-state">先从左侧载入一张图片，或上传自己的原稿。</div>
<p v-if="model&&!model.available" class="context-note">{{model.reason}}</p>
</Panel>
<Panel title="人工标注草稿" note="与原始文件哈希绑定">
<form @submit.prevent="save"><fieldset :disabled="!current||!original||busy||loading"><label class="lab-field">标注人<input v-model="annotator" @input="markDirty" required maxlength="80" placeholder="本人姓名或代号" aria-label="标注人"></label><label class="lab-field">可见文字释文<textarea v-model="transcription" @input="markDirty" rows="3" maxlength="300" placeholder="只填可辨认的文字，无法确认可留空" aria-label="人工释文"></textarea></label><label class="lab-field">可辨认情况<select v-model="legibility" @change="markDirty" aria-label="文字可辨认情况"><option value="unsure">尚未判断</option><option value="readable">可辨认</option><option value="partial">部分可辨认</option><option value="unreadable">无法辨认</option></select></label><label class="lab-field">残损与疑问记录<textarea v-model="notes" @input="markDirty" rows="5" maxlength="3000" placeholder="记录断笔、污渍、难辨字和依据；不猜测补全" aria-label="残损与疑问记录"></textarea></label><div class="context-note">{{loading?'读取已有草稿…':dirty?'有未保存的人工修改':saved?.annotation?'人工草稿已归档 · 待独立复核':'尚无人工草稿'}}<br>释文不会由增强模型自动生成。掩膜未绘制时记为“未标注”，不会生成空白真值。</div><button class="primary full" type="submit">保存人工草稿</button></fieldset></form><div v-if="saved?.annotation" class="lab-exports"><a class="button full" :href="saved.annotation.url" download>导出标注 JSON</a><a v-if="saved.mask" class="button full" :href="saved.mask.url" download>导出手绘掩膜 PNG</a><p class="hint">保存新版本会保留此前版本。当前草稿未获独立复核，不自动进入训练。</p></div><div v-if="original" class="lab-hash">原稿 SHA256<br><code>{{original.metadata.sha256}}</code></div>
</Panel>
</div>
<div v-if="discardOpen" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="discard-title"><h2 id="discard-title">人工草稿尚未保存</h2><p>继续切换会舍弃当前修改，已经归档的版本仍保留。可先留在本页保存草稿。</p><div class="actions"><button class="primary" autofocus @click="decideDiscard(false)">继续编辑</button><button @click="decideDiscard(true)">舍弃修改并切换</button></div></section></div>
</template>
<style scoped>
.lab-intro{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:16px 20px;border:1px solid #916039;border-radius:10px;background:#392216a6;margin-bottom:16px}.lab-intro p{font-size:13px;line-height:1.8;color:#d8b791;margin:10px 0 0}.lab-intro .button{white-space:nowrap}.lab-grid{display:grid;grid-template-columns:260px minmax(0,1fr) 340px;gap:16px;align-items:start}.lab-field{display:block;font-size:13px;color:#d9b588;line-height:1.8;margin-bottom:16px}.lab-field input,.lab-field textarea,.lab-field select{display:block;width:100%;margin-top:6px;box-sizing:border-box}.lab-field select{font-size:12px}.lab-filename{font-size:12px;color:#c8ab86;word-break:break-all;margin-bottom:12px}.candidate-preview{height:215px;display:grid;place-items:center;background:#f4ecd9;border-radius:7px;margin-bottom:12px}.candidate-preview img{max-width:92%;max-height:195px;object-fit:contain;image-rendering:auto}.full{margin-top:10px}.lab-comparison{display:grid;grid-template-columns:1fr 1fr;gap:12px}.lab-comparison figure{margin:0;min-width:0}.lab-comparison figure>div{height:185px;background:#f4ecd9;border-radius:7px;display:grid;place-items:center;overflow:hidden;color:#735637;font-size:13px}.lab-comparison img{max-width:94%;max-height:175px;object-fit:contain}.lab-comparison figcaption{font-size:11px;color:#c8ab86;text-align:center;padding:10px 0;line-height:1.6}.lab-paint-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:24px}.lab-paint-heading h3{font-size:16px;color:#eac790;margin:0}.lab-paint-heading .pill{font-size:10px}.lab-canvas{position:relative;width:min(100%,390px);margin:16px auto 12px;background:#f3e8d4;line-height:0;overflow:hidden;border:1px solid #94704d;border-radius:4px}.lab-canvas img{display:block;width:100%;height:auto;image-rendering:pixelated}.lab-canvas canvas{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.lab-canvas.painting canvas{pointer-events:auto;touch-action:none;cursor:crosshair}.lab-tools{display:flex;align-items:center;flex-wrap:wrap;gap:12px;font-size:12px;color:#d0b18a}.lab-tools label{display:flex;align-items:center;gap:6px}.lab-tools input[type=range]{width:80px;padding:0;min-height:0;accent-color:#df7640}.lab-tools button{font-size:11px;padding:6px 10px;min-height:30px}.lab-grid fieldset{margin:0;padding:0;min-width:0;border:0}.lab-grid fieldset:disabled{opacity:.65}.lab-hash{font-size:11px;color:#b39571;margin-top:20px;line-height:1.8}.lab-hash code{display:block;overflow-wrap:anywhere;color:#c5a985;font-size:10px}.lab-exports{margin-top:16px}.context-note{margin-top:20px}.hint{line-height:1.9}.lab-grid .empty-state{padding:40px 10px;line-height:1.9}
@media(max-width:1500px){.lab-grid{grid-template-columns:240px minmax(0,1fr)}.lab-grid>.panel:last-child{grid-column:1/-1}.lab-grid form fieldset{display:grid;grid-template-columns:1fr 1fr;gap:12px 20px}.lab-grid form .lab-field{margin-bottom:0}.lab-grid form .full{align-self:end}.lab-hash{max-width:500px}}
@media(max-width:900px){.lab-intro{align-items:flex-start;padding:14px;flex-direction:column;gap:10px}.lab-grid{grid-template-columns:1fr}.lab-grid>.panel:last-child{grid-column:auto}.lab-grid form fieldset{display:block}.lab-grid form .lab-field{margin-bottom:16px}.candidate-preview{height:180px}.candidate-preview img{max-height:165px}.lab-comparison figure>div{height:155px}.lab-comparison img{max-height:145px}.lab-paint-heading{flex-wrap:wrap}}
</style>
